#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1) {
        return 0;
    }
    Node *head = NULL;
    for (int i = 0; i < n; i++) {
        int x;
        if (scanf("%d", &x) != 1) {
            break;
        }
        Node *node = malloc(sizeof *node);
        if (node == NULL) {
            return 1;
        }
        node->value = x;
        node->next = head;
        head = node;
    }
    for (Node *p = head; p != NULL; p = p->next) {
        printf(p->next != NULL ? "%d " : "%d\n", p->value);
    }
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
    return 0;
}

