typedef struct Node {
    int value;
    struct Node *next;
} Node;

int main(void) {
    int n, x;
    if (scanf("%d %d", &n, &x) != 2 || n < 1) {
        return 0;
    }
    Node *head = NULL, *tail = NULL;
    for (int i = 0; i < n; i++) {
        int v;
        if (scanf("%d", &v) != 1) {
            break;
        }
        Node *node = malloc(sizeof *node);
        if (node == NULL) {
            return 1;
        }
        node->value = v;
        node->next = NULL;
        if (tail == NULL) {
            head = node;
        } else {
            tail->next = node;
        }
        tail = node;
    }
    Node **link = &head;
    while (*link != NULL) {
        Node *node = *link;
        if (node->value == x) {
            *link = node->next;
            free(node);
        } else {
            link = &node->next;
        }
    }
    if (head == NULL) {
        printf("пусто\n");
    }
    for (Node *p = head; p != NULL; p = p->next) {
        printf(p->next != NULL ? "%d " : "%d\n", p->value);
    }
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
    return 0;
}

