#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int id;
    struct Node *next;
} Node;

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 1000) {
        return 0;
    }
    Node *nodes[1000];
    for (int i = 0; i < n; i++) {
        nodes[i] = malloc(sizeof *nodes[i]);
        if (nodes[i] == NULL) {
            return 1;
        }
        nodes[i]->id = i;
    }
    for (int i = 0; i < n; i++) {
        int next;
        scanf("%d", &next);
        nodes[i]->next = next >= 0 ? nodes[next] : NULL;
    }
    Node *slow = nodes[0], *fast = nodes[0];
    int cycle = 0;
    while (fast != NULL && fast->next != NULL) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {
            cycle = 1;
            break;
        }
    }
    if (!cycle) {
        printf("нет цикла\n");
    } else {
        int length = 1;
        for (Node *p = slow->next; p != slow; p = p->next) {
            length++;
        }
        Node *a = nodes[0], *b = slow;
        while (a != b) {
            a = a->next;
            b = b->next;
        }
        printf("цикл: начало %d, длина %d\n", a->id, length);
    }
    for (int i = 0; i < n; i++) {
        free(nodes[i]);
    }
    return 0;
}

